<script setup lang="ts">
import { ref,watch } from 'vue';
import { readArtifact,type Artifact } from '../services/library';
const props=defineProps<{artifact:Artifact;disabled?:boolean}>(),emit=defineEmits<{saved:[value:Artifact];deleted:[];busy:[value:boolean]}>();
const editing=ref(false),deleting=ref(false),busy=ref(false),error=ref(''),title=ref(''),content=ref(''),revisions=ref<{revision:number;title:string;content:string;status:string;savedAt:string}[]>([]);
watch(()=>[props.artifact.id,props.artifact.revision],()=>{editing.value=false;deleting.value=false;title.value=props.artifact.title;content.value=props.artifact.content;revisions.value=[];error.value='';},{immediate:true});
async function act(action:'edit'|'approve'|'delete'|'revisions'){
 const id=props.artifact.id;busy.value=true;emit('busy',true);error.value='';
 try{const response=await fetch(`/api/artifacts/${id}/manage/${action}`,action==='revisions'?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:props.artifact.revision??0,...(action==='edit'?{title:title.value,content:content.value}:{})})});const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.error?.message??'No se pudo actualizar el documento.');if(id!==props.artifact.id)return;if(action==='revisions')revisions.value=result.revisions;else if(action==='delete')emit('deleted');else emit('saved',await readArtifact(id));}
 catch(cause){error.value=(cause as Error).message;}finally{busy.value=false;emit('busy',false);}
}
</script>
<template><section class="document-editor" aria-label="Gestión del documento"><p class="result-note">Revisión {{ artifact.revision??0 }} · {{ artifact.status==='APPROVED'?'APROBADO POR EL USUARIO':'BORRADOR' }}<span v-if="artifact.updatedAt"> · {{ new Date(artifact.updatedAt).toLocaleString('es-PE') }}</span></p><div class="source-actions"><button class="connection-action" :disabled="disabled||busy" @click="editing=!editing">Editar documento</button><button v-if="artifact.status!=='APPROVED'" class="connection-action" :disabled="disabled||busy||editing" @click="act('approve')">Aprobar revisión</button><button class="connection-action" :disabled="disabled||busy" @click="act('revisions')">Ver revisiones anteriores</button><button class="connection-action" :disabled="disabled||busy" @click="deleting=!deleting">Eliminar documento</button></div><form v-if="editing" class="document-form" @submit.prevent="act('edit')"><label for="edit-document-title">Título del documento</label><input id="edit-document-title" v-model="title" maxlength="255" :disabled="disabled||busy"/><label for="edit-document-content">Contenido del documento</label><textarea id="edit-document-content" v-model="content" maxlength="60000" rows="16" :disabled="disabled||busy"/><p class="result-note">Guardar crea una revisión, vuelve a borrador e invalida los embeddings anteriores. Debes preparar de nuevo su memoria.</p><button class="primary-button" :disabled="disabled||busy||!title.trim()||!content.trim()">Guardar revisión</button></form><div v-if="deleting" class="delete-review"><p>Eliminar {{ artifact.title }} retirará el documento, sus revisiones y sus embeddings. Las conversaciones conservan las citas que recibieron al responder.</p><button class="connection-action" :disabled="disabled||busy" @click="act('delete')">Confirmar eliminación del documento</button></div><p v-if="error" class="library-error" role="alert">{{ error }}</p><details v-for="revision in revisions" :key="revision.revision"><summary>Revisión {{ revision.revision }} · {{ revision.status }} · {{ revision.title }}</summary><pre>{{ revision.content }}</pre></details></section></template>
<style scoped>.document-editor{padding:18px 0;border-top:1px solid #233a41;margin-top:20px}.document-form{display:grid;gap:12px;margin:20px 0}.document-form input,.document-form textarea{width:100%;padding:12px;background:#08151a;border:1px solid #29434b;color:#dcebf0;border-radius:6px}.document-form button{justify-self:start}.document-editor pre{max-height:300px;overflow:auto;font-size:12px}.delete-review{padding:15px;border:1px solid #925c51;margin:20px 0}</style>
